 1	method twoSum(nums: array<int>, target: int) returns (index1: int, index2: int)
 2	    requires 2 <= nums.Length
 3	    requires exists i, j :: (0 <= i < j < nums.Length && nums[i] + nums[j] == target)
 4	    ensures index1 != index2
 5	    ensures 0 <= index1 < nums.Length
 6	    ensures 0 <= index2 < (nums.Length) - 1
 7	    ensures nums[index1] + nums[index2] == target
 8	{
 9	    var i := 0;
10	    while i < nums.Length
11	        invariant 0 <= i < nums.Length
12	        invariant forall u, v :: 0 <= u < v < nums.Length && u < i ==> nums[u] + nums[v] != target
13	        invariant exists u, v :: i <= u < v < nums.Length && nums[u] + nums[v] == target
14	    {
15	        var j := i + 1;
16	        while j < nums.Length
17	            invariant 0 <= i < j <= nums.Length
18	            invariant forall u, v :: 0 <= u < v < nums.Length && u < i ==> nums[u] + nums[v] != target
19	            invariant exists u, v :: i <= u < v < nums.Length && nums[u] + nums[v] == target
20	            invariant forall u :: i < u < j ==> nums[i] + nums[u] != target
21	        {
22	            if nums[i] + nums[j] == target
23	            {
24	                return i, j;
25	            } 
26	            j := j + 1;
27	        }
28	        i := i + 1;
29	    }
30	}
